def handle_query(nums1, nums2, queries):
    total = sum(nums2)
    nums1 = nums1[:]
    result = []
    for q in queries:
        if q[0] == 1:
            for i in range(q[1], q[2] + 1):        # flip every bit in the range directly
                nums1[i] ^= 1
        elif q[0] == 2:
            ones = sum(nums1)                          # re-sum from scratch
            total += ones * q[1]
        else:
            result.append(total)
    return result

