vector<long long> handleQuery(vector<int>& nums1, vector<int>& nums2, vector<vector<int>>& queries) {
    long long total = 0;
    for (int x : nums2) total += x;
    vector<int> arr = nums1;
    vector<long long> result;
    for (auto& q : queries) {
        if (q[0] == 1) {
            for (int i = q[1]; i <= q[2]; i++) arr[i] ^= 1;          // flip every bit directly
        } else if (q[0] == 2) {
            long long ones = 0;
            for (int x : arr) ones += x;                                 // re-sum from scratch
            total += ones * (long long)q[1];
        } else {
            result.push_back(total);
        }
    }
    return result;
