class SegTree:
    def __init__(self, nums):
        self.n = len(nums)
        self.tree = [0] * (4 * self.n)
        self.lazy = [False] * (4 * self.n)
        self.nums = nums
        self.build(0, 0, self.n - 1)

    def build(self, node, start, end):
        if start == end:
            self.tree[node] = self.nums[start]
            return
        mid = (start + end) // 2
        self.build(2 * node + 1, start, mid)
        self.build(2 * node + 2, mid + 1, end)
        self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]

    def push_down(self, node, start, end):
        if self.lazy[node]:
            mid = (start + end) // 2
            left_len, right_len = mid - start + 1, end - mid
            self.tree[2 * node + 1] = left_len - self.tree[2 * node + 1]
            self.tree[2 * node + 2] = right_len - self.tree[2 * node + 2]
            self.lazy[2 * node + 1] ^= True
            self.lazy[2 * node + 2] ^= True
            self.lazy[node] = False

    def update(self, node, start, end, l, r):
        if r < start or end < l:
            return
        if l <= start and end <= r:
            self.tree[node] = (end - start + 1) - self.tree[node]   # flip: count = length - count, O(1)
            self.lazy[node] ^= True
            return
        self.push_down(node, start, end)
        mid = (start + end) // 2
        self.update(2 * node + 1, start, mid, l, r)
        self.update(2 * node + 2, mid + 1, end, l, r)
        self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]

    def total_ones(self):
        return self.tree[0]                                            # O(1), root holds the total


def handle_query(nums1, nums2, queries):
    total = sum(nums2)
    seg = SegTree(nums1)
    result = []
    for q in queries:
        if q[0] == 1:
            seg.update(0, 0, seg.n - 1, q[1], q[2])       # O(log n) range flip
        elif q[0] == 2:
            total += seg.total_ones() * q[1]                # O(1) total-ones lookup
        else:
            result.append(total)
    return result

