#include <bits/stdc++.h>
using namespace std;

vector<long long> tree;
vector<bool> lazy;

void build(vector<int>& nums, int node, int start, int end) {
    if (start == end) { tree[node] = nums[start]; return; }
    int mid = (start + end) / 2;
    build(nums, 2 * node + 1, start, mid);
    build(nums, 2 * node + 2, mid + 1, end);
    tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
}

void pushDown(int node, int start, int end) {
    if (lazy[node]) {
        int mid = (start + end) / 2;
        tree[2 * node + 1] = (mid - start + 1) - tree[2 * node + 1];
        tree[2 * node + 2] = (end - mid) - tree[2 * node + 2];
        lazy[2 * node + 1] = !lazy[2 * node + 1];
        lazy[2 * node + 2] = !lazy[2 * node + 2];
        lazy[node] = false;
    }
}

void update(int node, int start, int end, int l, int r) {
    if (r < start || end < l) return;
    if (l <= start && end <= r) {
        tree[node] = (end - start + 1) - tree[node];   // flip: count = length - count, O(1)
        lazy[node] = !lazy[node];
        return;
    }
    pushDown(node, start, end);
    int mid = (start + end) / 2;
    update(2 * node + 1, start, mid, l, r);
    update(2 * node + 2, mid + 1, end, l, r);
    tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
}
